        .@"errdefer" => 92,
        .@"pre" => 93,
        .@"raw" => 94,
        .@"pub" => 95,
        .@"use" => 96,
        .@"fun" => 97,
        .@"sub" => 98,
        .@"lparen_call" => 103,
        .@"read_pfx" => 105,
        .@"write_pfx" => 106,
        .@"kwarg_name" => 107,
        .@"enum" => 108,
        .@"error" => 109,
        .@"struct" => 110,
