        48 => pass[0],
        49 => self.build(&.{ .{ .tag = .@"pub" }, pass[1] }, .tree),
        50 => pass[0],
        51 => pass[0],
        52 => pass[0],
        53 => pass[0],
        54 => pass[0],
        55 => pass[0],
        56 => pass[0],
        57 => self.build(&.{ .{ .tag = .@"use" }, pass[1] }, .tree),
        58 => self.build(&.{ .{ .tag = .@"fun" }, pass[1], .nil, .nil, pass[2] }, .tree),
