        60 => self.build(&.{ .{ .tag = .@"fun" }, pass[1], .nil, pass[2], pass[3] }, .tree),
        61 => self.build(&.{ .{ .tag = .@"fun" }, pass[1], pass[2], pass[3], pass[4] }, .tree),
